"""Core LedgerLock implementation: append-only, tamper-evident key/value ledger.

This module is pure standard library (see docs/requirements.md §10 and §12).
"""

from __future__ import annotations

import hashlib
import json
import os
import tempfile
import unicodedata
from pathlib import Path
from typing import Any, Iterable

#: The literal predecessor of the first record's hash. Constant per §3.2.
GENESIS = "GENESIS"


def _normalize_key(key: str) -> str:
    return unicodedata.normalize("NFC", key)


def _canonical_line(obj: dict[str, Any]) -> bytes:
    """Canonical byte serialization of a JSONL record.

    Deterministic: keys sorted, compact separators, no ASCII escaping.
    """
    return json.dumps(
        obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def _hash_line(prev_hash: str, canonical: bytes) -> str:
    return hashlib.sha256(prev_hash.encode("utf-8") + b"|" + canonical).hexdigest()


class ConflictError(Exception):
    """Raised when a mutation conflicts with the last committed mutation for a key."""


class Ledger:
    """Append-only, hash-chained, idempotent key/value ledger."""

    GENESIS = GENESIS

    def __init__(self, path: str | os.PathLike[str]) -> None:
        self.path = Path(path)
        # key -> (rid, op, value, ts, hash) of the last committed mutation.
        self._last: dict[str, tuple[str, str, Any, int, str]] = {}
        self._tail_hash: str = self.GENESIS
        self._reload()

    def _reload(self) -> None:
        self._last = {}
        self._tail_hash = self.GENESIS
        if not self.path.exists():
            return
        with open(self.path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.rstrip("\n")
                if line == "":
                    continue
                try:
                    obj = json.loads(line)
                except json.JSONDecodeError:
                    break  # stop at a malformed (e.g. truncated) tail line
                if not isinstance(obj, dict):
                    break
                key = obj["key"]
                self._last[key] = (
                    obj["id"],
                    obj["op"],
                    obj.get("value"),
                    obj["ts"],
                    obj["hash"],
                )
                self._tail_hash = obj["hash"]

    def _validate(self, op: str, key: str, value: Any, rid: Any, ts: Any) -> str:
        if op not in ("put", "delete"):
            raise ValueError("op must be 'put' or 'delete'")
        if not isinstance(rid, str) or rid == "":
            raise ValueError("rid must be a non-empty string")
        if isinstance(ts, bool) or not isinstance(ts, int):
            raise ValueError("ts must be an int")
        return _normalize_key(key)

    def _make_line(self, op: str, key: str, value: Any, rid: str, ts: int) -> dict[str, Any]:
        obj: dict[str, Any] = {"op": op, "key": key, "ts": ts, "id": rid}
        if op == "put":
            obj["value"] = value
        return obj

    def _chain_hash(self, prev_hash: str, line: dict[str, Any]) -> str:
        canon = dict(line)
        canon["hash"] = ""
        canon["prev_hash"] = ""
        return _hash_line(prev_hash, _canonical_line(canon))

    def _write_line(self, line: dict[str, Any]) -> None:
        data = _canonical_line(line) + b"\n"
        with open(self.path, "ab") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())

    def append(
        self,
        op: str,
        key: str,
        value: Any = None,
        rid: str | None = None,
        ts: int | None = None,
    ) -> str:
        """Append a single mutation. Returns the hex hash of the committed line.

        Idempotent: replaying the same rid returns the same hash and appends nothing.
        Raises ConflictError if the key's last committed mutation used a different rid.
        """
        key = self._validate(op, key, value, rid, ts)
        prev = self._last.get(key)
        if prev is not None:
            if prev[0] == rid:
                return prev[4]
            raise ConflictError(
                f"key {key!r} was last mutated by rid {prev[0]!r}, not {rid!r}"
            )
        line = self._make_line(op, key, value, rid, ts)
        h = self._chain_hash(self._tail_hash, line)
        line["prev_hash"] = self._tail_hash
        line["hash"] = h
        self._write_line(line)
        self._tail_hash = h
        self._last[key] = (rid, op, value, ts, h)
        return h

    def verify(self) -> dict[str, Any]:
        """Independently recompute the hash chain from disk end-to-end.

        Returns {"ok": bool, "first_bad_index": int | None}.
        """
        if not self.path.exists():
            return {"ok": True, "first_bad_index": None}
        prev_hash = self.GENESIS
        with open(self.path, "r", encoding="utf-8") as f:
            for i, line in enumerate(f):
                line = line.rstrip("\n")
                try:
                    obj = json.loads(line)
                except json.JSONDecodeError:
                    return {"ok": False, "first_bad_index": i}
                if not isinstance(obj, dict):
                    return {"ok": False, "first_bad_index": i}
                if "hash" not in obj or "prev_hash" not in obj:
                    return {"ok": False, "first_bad_index": i}
                stored_hash = obj["hash"]
                stored_prev = obj["prev_hash"]
                canon = dict(obj)
                canon["hash"] = ""
                canon["prev_hash"] = ""
                recomputed = _hash_line(stored_prev, _canonical_line(canon))
                if recomputed != stored_hash:
                    return {"ok": False, "first_bad_index": i}
                if stored_prev != prev_hash:
                    return {"ok": False, "first_bad_index": i}
                prev_hash = stored_hash
        return {"ok": True, "first_bad_index": None}

    def snapshot(self) -> dict[str, Any]:
        """Return the materialized state, keyed by NFC-normalized key, sorted.

        Deterministic: same chain content yields the same dict (and serialized bytes).
        """
        result: dict[str, Any] = {}
        for key in sorted(self._last):
            rid, op, value, ts, h = self._last[key]
            if op == "put":
                result[key] = value
        return result

    def apply_batch(self, ops: Iterable[tuple]) -> None:
        """Atomically apply an iterable of (op, key, value, rid, ts) tuples.

        All-or-nothing: writes to a sibling temp file, fsyncs, then renames.
        """
        working = dict(self._last)
        tail_hash = self._tail_hash
        new_lines: list[dict[str, Any]] = []
        for op, key, value, rid, ts in ops:
            key = self._validate(op, key, value, rid, ts)
            prev = working.get(key)
            if prev is not None:
                if prev[0] == rid:
                    continue
                raise ConflictError(
                    f"key {key!r} was last mutated by rid {prev[0]!r}, not {rid!r}"
                )
            line = self._make_line(op, key, value, rid, ts)
            h = self._chain_hash(tail_hash, line)
            line["prev_hash"] = tail_hash
            line["hash"] = h
            tail_hash = h
            working[key] = (rid, op, value, ts, h)
            new_lines.append(line)

        if not new_lines:
            return

        self._atomic_append(new_lines)
        self._last = working
        self._tail_hash = tail_hash

    def _atomic_append(self, new_lines: list[dict[str, Any]]) -> None:
        parent = str(self.path.parent) or "."
        fd, tmp = tempfile.mkstemp(
            dir=parent, prefix=self.path.name + ".", suffix=".tmp"
        )
        try:
            with os.fdopen(fd, "wb") as f:
                if self.path.exists():
                    with open(self.path, "rb") as src:
                        while True:
                            chunk = src.read(65536)
                            if not chunk:
                                break
                            f.write(chunk)
                for line in new_lines:
                    f.write(_canonical_line(line) + b"\n")
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, self.path)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise


def append(
    path: str | os.PathLike[str],
    op: str,
    key: str,
    value: Any = None,
    rid: str | None = None,
    ts: int | None = None,
) -> str:
    """Append a single mutation to the ledger at ``path`` and return its hex hash.

    Module-level convenience wrapper around :meth:`Ledger.append`. The same
    idempotency and conflict rules apply (see docs/requirements.md §4).
    """
    return Ledger(path).append(op, key, value, rid, ts)


def snapshot(path: str | os.PathLike[str]) -> dict[str, Any]:
    """Return the materialized state of the ledger at ``path``.

    Module-level convenience wrapper around :meth:`Ledger.snapshot`. Returns a
    deterministic dict mapping each NFC-normalized key to its latest committed
    ``put`` value, sorted by key, with tombstoned keys omitted (see
    docs/requirements.md §6).
    """
    return Ledger(path).snapshot()


def verify(path: str | os.PathLike[str]) -> dict[str, Any]:
    """Independently verify the hash chain of the ledger at ``path``.

    Module-level convenience wrapper around :meth:`Ledger.verify`. Reads and
    recomputes the chain from disk only, never from in-memory state
    (docs/requirements.md §3.4).
    """
    return Ledger(path).verify()


def apply_batch(path: str | os.PathLike[str], ops: Iterable[tuple]) -> None:
    """Atomically apply a batch of mutations to the ledger at ``path``.

    Module-level convenience wrapper around :meth:`Ledger.apply_batch`. The
    same all-or-nothing, idempotency, and conflict rules apply
    (docs/requirements.md §4 and §5).
    """
    Ledger(path).apply_batch(ops)

